<?php
// SARMAD Attendance - 1-Click Complete System Updater (Camera + Kiosk Fixes)
header("Content-Type: text/html; charset=UTF-8");

$baseDir = __DIR__;
$results = [];

$files = [
    "assets/.htaccess" => "",
    "assets/css/device.css" => "",
    "assets/css/manager.css" => "",
    "assets/css/app.css" => "",
    "app/Services/DeviceService.php" => "",
    "app/Controllers/DeviceController.php" => "",
    "app/Controllers/Manager/DeviceController.php" => "",
    "views/manager/employees/profile.php" => "",
    "views/manager/employees/index.php" => ""
];

foreach ($files as $relPath => $b64) {
    $target = $baseDir . "/" . $relPath;
    $dir = dirname($target);
    if (!is_dir($dir)) {
        @mkdir($dir, 0755, true);
    }
    $data = base64_decode($b64);
    $ok = @file_put_contents($target, $data);
    if ($ok !== false) {
        $results[] = ["path" => $relPath, "status" => "success", "msg" => "با موفقیت به‌روزرسانی شد (" . strlen($data) . " بایت)"];
    } else {
        $results[] = ["path" => $relPath, "status" => "error", "msg" => "خطا در ذخیره فایل"];
    }
}
?>
