    <div>
        <?php foreach ($results as $res): ?>
            <div class="item <?php echo $res["status"] === "error" ? "error" : ""; ?>">
                <strong><?php echo htmlspecialchars($res["path"]); ?></strong>
                <span><?php echo $res["msg"]; ?></span>
            </div>
        <?php endforeach; ?>
